class CourseRecord:
    def __init__(self, name, hours):
        self.name = name
        self.hours = hours

    def get_hours(self):
        return self.hours

    def set_hours(self, hours):
        self.hours = hours

record = CourseRecord("AI", 3)
print(record.get_hours())
record.set_hours(5)
print(record.get_hours())
